"    // 跨源 iframe 的探针消息：主框架代为转发给原生。\n"
"    if (d.__meo === 'dom-inspector-payload') {\n"
"      try { window.webkit.messageHandlers.meoDomInspector.postMessage(d.payload); } catch (x) {}\n"
"      return;\n"
"    }\n"
"    if (d.__meo === 'dom-inspector-diag') {\n"
"      try { window.webkit.messageHandlers.meoDomInspector.postMessage(d); } catch (x) {}\n"
"      return;\n"
"    }\n"
"    if (d.__meo !== 'dom-inspector') { return; }\n"
"    if (d.unpin) {\n"
"      try {\n"
"        if (typeof window.__meoDomInspectorUnpin === 'function') {\n"
"          window.__meoDomInspectorUnpin();\n"
"        }\n"
"      } catch (x) {}\n"
"      try {\n"
"        var ufs = document.querySelectorAll('iframe,frame');\n"
"        for (var ui = 0; ui < ufs.length; ui++) {\n"
"          try { ufs[ui].contentWindow.postMessage({__meo:'dom-inspector',unpin:1}, '*'); } catch (x) {}\n"
"        }\n"
"      } catch (x) {}\n"
"      return;\n"
"    }\n"
"    if (d.pinLast) {\n"
"      try {\n"
"        if (typeof window.__meoDomInspectorPinLast === 'function') {\n"
"          window.__meoDomInspectorPinLast();\n"
"        }\n"
"      } catch (x) {}\n"
"      try {\n"
"        var pfs = document.querySelectorAll('iframe,frame');\n"
"        for (var pi = 0; pi < pfs.length; pi++) {\n"
"          try { pfs[pi].contentWindow.postMessage({__meo:'dom-inspector',pinLast:1}, '*'); } catch (x) {}\n"
"        }\n"
"      } catch (x) {}\n"
"      return;\n"
"    }\n"
"    window.__meoDomInspectorApply(!!d.on);\n"
"    // 继续向下转发，覆盖嵌套的子框架。\n"
"    try {\n"
"      var fs = document.querySelectorAll('iframe,frame');\n"
"      for (var i = 0; i < fs.length; i++) {\n"
"        try { fs[i].contentWindow.postMessage({__meo:'dom-inspector','on':!!d.on}, '*'); } catch (x) {}\n"
"      }\n"
"    } catch (x) {}\n"
"  }, false);\n"
"})();";
}

+ (NSString *)enableScript {
    return
    @"(function() {\n"
    @"  try {\n"
    @"    if (window.__meoDomInspectorStart) { window.__meoDomInspectorStart(); }\n"
    @"  } catch (e) {}\n"
    @"})();";
}

+ (NSString *)disableScript {
    return
    @"(function() {\n"
    @"  try {\n"
    @"    if (window.__meoDomInspectorStop) { window.__meoDomInspectorStop(); }\n"
    @"  } catch (e) {}\n"
    @"})();";
}

@end
